    var raw = String(source.getVariable() || '');
    o = raw ? (JSON.parse(raw) || {}) : {};
  } catch (e0) { o = {}; }
  if (!o.page) o.page = '1';
  o.pnLine = String(line || '');
  try { source.setVariable(JSON.stringify(o)); } catch (e) {}
  return o;
}
function PN_base() {
  var ok = function (v) {
    var s = '';
    try { s = String(v); } catch (e) { return ''; }
    return (s && s !== 'null' && s !== 'undefined' && s.indexOf('http') === 0) ? s : '';
  };
  var d = '';
  // ① 主通道：variable.pnLine（this.source 在 {{}} 共享 scope 可用，诊断版4 实锤）
